                'message'    => 'Cryptographic digital signature is invalid or has been tampered with.',
                'machine_id' => $currentMachineId,
                'payload'    => $payload,
            ];
        }

        // 2. Anti-Clock Rollback Detection
        if (self::isClockTampered()) {
            return [
                'valid'      => false,
                'code'       => 'CLOCK_TAMPERING',
                'message'    => 'System clock manipulation detected. System time cannot be set behind previous records.',
                'machine_id' => $currentMachineId,
                'payload'    => $payload,
            ];
        }

        // 3. Verify Hardware Binding (Machine ID match with normalization)
        $licensedMachineId = MachineFingerprint::normalizeMachineId((string)($payload['machine_id'] ?? ''));
        $normCurrentMachineId = MachineFingerprint::normalizeMachineId($currentMachineId);
        if (empty($licensedMachineId) || empty($normCurrentMachineId) || $licensedMachineId !== $normCurrentMachineId) {
            return [
                'valid'      => false,
                'code'       => 'HARDWARE_MISMATCH',
                'message'    => sprintf(
                    'License is locked to machine [%s], but this machine is [%s].',
                    $payload['machine_id'] ?? 'UNKNOWN',
                    $currentMachineId
                ),
                'machine_id' => $currentMachineId,
                'payload'    => $payload,
            ];
        }

        // 4. Verify Expiration Date (if time-limited)
        if (!empty($payload['expires_at'])) {
            $expTime = strtotime($payload['expires_at']);
            if ($expTime === false) {
                return [
                    'valid'      => false,
                    'code'       => 'LICENSE_CORRUPTED_DATE',
                    'message'    => 'License expiration date format is invalid or unparseable.',
                    'machine_id' => $currentMachineId,
                    'payload'    => $payload,
                ];
            }
            if (time() > $expTime) {
                return [
                    'valid'      => false,
                    'code'       => 'LICENSE_EXPIRED',
                    'message'    => 'This license expired on ' . date('Y-m-d H:i:s', $expTime) . '.',
                    'machine_id' => $currentMachineId,
                    'payload'    => $payload,
                ];
            }
        } elseif (isset($payload['plan']) && $payload['plan'] === 'subscription') {
            return [
                'valid'      => false,
                'code'       => 'LICENSE_CORRUPTED',
                'message'    => 'Subscription licenses must specify a valid expiration date.',
                'machine_id' => $currentMachineId,
                'payload'    => $payload,
            ];
        }

        // 5. Verify Authorship Triad Steganographic Anchors
        $triadCheck = self::verifyAuthorshipTriad();
        if (!$triadCheck['valid']) {
            return [
                'valid'      => false,
                'code'       => $triadCheck['code'],
                'message'    => $triadCheck['message'],
                'machine_id' => $currentMachineId,
                'payload'    => $payload,
            ];
        }

        return [
            'valid'      => true,
            'code'       => 'OK',
            'message'    => 'License is authentic and verified for this machine.',
            'machine_id' => $currentMachineId,
            'payload'    => $payload,
        ];
    }

    /**
     * Retrieves the array of store presets permitted by the license payload.
     *
     * @param array|null $payload Optional decoded license payload. If null, active license is inspected.
     * @return string[] Array of allowed presets (e.g. ['phone_repair', 'crypto_cash']) or ['*'] for unrestricted.
     */
    public static function getAllowedStores(?array $payload = null): array
    {
        if ($payload === null) {
            $status = self::checkLicenseStatus();
            if (empty($status['valid']) || !is_array($status['payload'])) {
                return [];
            }
            $payload = $status['payload'];
        }

        // Support both 'allowed_stores' and 'stores' keys
        $stores = $payload['allowed_stores'] ?? $payload['stores'] ?? null;

        // Legacy license without store constraints -> All stores allowed (100% backward compatibility)
        if ($stores === null) {
            return ['*'];
        }

        // Wildcard string or single string
        if (is_string($stores)) {
            $trimmed = trim($stores);
            if ($trimmed === '*' || strtolower($trimmed) === 'all') {
                return ['*'];
            }
            return $trimmed !== '' ? [$trimmed] : ['*'];
        }

        // Array of stores
        if (is_array($stores)) {
            $normalized = [];
            foreach ($stores as $s) {
                if (is_string($s)) {
                    $clean = trim($s);
                    if ($clean === '*' || strtolower($clean) === 'all') {
                        return ['*'];
                    }
                    if ($clean !== '') {
                        $normalized[] = $clean;
                    }
                }
            }
            return !empty($normalized) ? array_values(array_unique($normalized)) : ['*'];
        }

        return ['*'];
    }

    /**
     * Determines whether a given store preset is permitted by the active license.
     *
     * @param string $preset Preset key to check (e.g., 'phone_repair', 'crypto_cash')
     * @param array|null $payload Optional decoded license payload
     * @return bool True if permitted, false if forbidden
     */
    public static function isStoreAllowed(string $preset, ?array $payload = null): bool
    {
        $allowed = self::getAllowedStores($payload);
        if (empty($allowed)) {
            return false;
        }
        if (in_array('*', $allowed, true) || in_array('all', $allowed, true)) {
            return true;
        }
        return in_array($preset, $allowed, true);
    }

    /**
     * Verifies the cryptographic RSA-2048 signature of a canonicalized payload.
     */
    public static function verifySignature(array $payload, string $signatureBase64): bool
    {
        $signature = base64_decode($signatureBase64, true);
        if ($signature === false) {
            return false;
        }

        // Canonical JSON: sorted keys, unescaped slashes & unicode
        ksort($payload);
        $canonical = json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);

        $result = openssl_verify($canonical, $signature, self::PUBLIC_KEY, OPENSSL_ALGO_SHA256);
        return $result === 1;
    }

    /**
     * Extracts and decodes hidden zero-width steganographic text from arbitrary content.
     */
    public static function extractZeroWidthPayload(string $content): ?string
    {
        $startPos = strpos($content, self::ZW_START);
        if ($startPos === false) {
            return null;
        }

        $endPos = strpos($content, self::ZW_END, $startPos + strlen(self::ZW_START));
        if ($endPos === false) {
            return null;
        }

        $payload = substr($content, $startPos + strlen(self::ZW_START), $endPos - ($startPos + strlen(self::ZW_START)));

        $bits = '';
        $pLen = strlen($payload);
        $i = 0;
        $zwZeroLen = strlen(self::ZW_ZERO);
        $zwOneLen  = strlen(self::ZW_ONE);

        while ($i < $pLen) {
            if (substr($payload, $i, $zwZeroLen) === self::ZW_ZERO) {
                $bits .= '0';
                $i += $zwZeroLen;
            } elseif (substr($payload, $i, $zwOneLen) === self::ZW_ONE) {
                $bits .= '1';
                $i += $zwOneLen;
            } else {
                $i++;
            }
        }

        if (strlen($bits) % 8 !== 0) {
            return null;
        }

        $text = '';
        $numBytes = intdiv(strlen($bits), 8);
        for ($b = 0; $b < $numBytes; $b++) {
            $byteBits = substr($bits, $b * 8, 8);
            $text .= chr((int) bindec($byteBits));
        }

        return $text;
    }

