    /**
     * Continuous Runtime Sentinel:
     * Autonomous re-verification with 10-minute validity caching.
     * Drops ongoing execution time to 0.02ms.
     *
     * @return array{valid: bool, code: string, error?: string, machine_id: string}
     */
    public static function verifyRuntime(): array
    {
        // 0. Pre-Flight Host Environment Sentinel Audit
        $envAudit = EnvironmentSentinel::auditEnvironment();
        if (!$envAudit['safe']) {
            EnvironmentSentinel::enforceHardFailure($envAudit['code'], $envAudit['reason']);
        }

        $cache = self::readCache();
        $expectedSeal = MachineFingerprint::getHostSeal();

        // Assert Host Seal on Cache to prevent portable cache replay across machines
        if (!empty($cache)) {
            $cachedSeal = (string)($cache['host_seal'] ?? '');
            if (empty($cachedSeal) || !hash_equals($expectedSeal, $cachedSeal)) {
                self::purgeCache();
                $cache = [];
            }
        }

        // If system is already locked, check if a new license.json was dropped after the lock
        if (!empty($cache['is_locked'])) {
            if (is_file(self::LICENSE_PATH) && filemtime(self::LICENSE_PATH) > (int) ($cache['last_verified_at'] ?? 0)) {
                self::purgeCache();
                return self::verifyRuntime();
            }
            return [
                'valid'      => false,
                'code'       => $cache['lock_code'] ?? 'LICENSE_MISMATCH',
                'error'      => "You cannot use this system anymore because you don't have the right license.",
                'machine_id' => $cache['machine_id'] ?? self::getMachineId(false),
            ];
        }

        $now = time();
        $lastChecked = (int) ($cache['last_verified_at'] ?? 0);
        $delta = $now - $lastChecked;

        // Anti-Clock Rollback Detection:
        // If current time is backward relative to last verification timestamp (by > 60 seconds),
        // immediately trip CLOCK_TAMPERING lockout!
        if ($lastChecked > 0 && $delta < -60) {
            self::writeCache([
                'is_locked'        => true,
                'lock_code'        => 'CLOCK_TAMPERING',
                'lock_reason'      => 'System clock manipulation detected (backward time shift).',
                'last_verified_at' => $now,
                'machine_id'       => $cache['machine_id'] ?? self::getMachineId(false),
                'host_seal'        => $expectedSeal,
            ]);

            try {
                if (is_file(__DIR__ . '/../../config/database.php')) {
                    require_once __DIR__ . '/../Database.php';
                    require_once __DIR__ . '/../SystemLog.php';
                    $db = Database::getConnection();
                    $db->exec("UPDATE users SET active_session_id = NULL");
                    SystemLog::write('security', 'clock_tampering_lockout', null, 'System License Sentinel', json_encode([
                        'code'       => 'CLOCK_TAMPERING',
                        'delta'      => $delta,
                        'machine_id' => $cache['machine_id'] ?? self::getMachineId(false),
                    ]));
                }
            } catch (\Throwable $e) {}

            return [
                'valid'      => false,
                'code'       => 'CLOCK_TAMPERING',
                'error'      => "You cannot use this system anymore because you don't have the right license.",
                'machine_id' => $cache['machine_id'] ?? self::getMachineId(false),
            ];
        }

        // Within 10-minute cadence window: allow fast pass (0.02ms)
        if ($lastChecked > 0 && $delta >= 0 && $delta < self::CADENCE_SECONDS) {
            return [
                'valid'      => true,
                'code'       => 'OK',
                'machine_id' => $cache['machine_id'] ?? self::getMachineId(false),
            ];
        }

        // Cadence expired: perform full verification with physical hardware re-evaluation
        $status = self::checkLicenseStatus(true);

        if (!$status['valid']) {
            // TRIP THE HARD LOCKOUT
            self::writeCache([
                'is_locked'        => true,
                'lock_code'        => $status['code'],
                'lock_reason'      => $status['message'],
                'last_verified_at' => $now,
                'machine_id'       => $status['machine_id'],
                'host_seal'        => $expectedSeal,
            ]);

            // Invalidate all active sessions in DB and log security alert
            try {
                if (is_file(__DIR__ . '/../../config/database.php')) {
                    require_once __DIR__ . '/../Database.php';
                    require_once __DIR__ . '/../SystemLog.php';
                    $db = Database::getConnection();
                    $db->exec("UPDATE users SET active_session_id = NULL");
                    SystemLog::write('security', 'license_hard_lockout', null, 'System License Sentinel', json_encode([
                        'code'       => $status['code'],
                        'reason'     => $status['message'],
                        'machine_id' => $status['machine_id'],
                    ]));
                }
            } catch (\Throwable $e) {}

            return [
                'valid'      => false,
                'code'       => $status['code'],
                'error'      => "You cannot use this system anymore because you don't have the right license.",
                'machine_id' => $status['machine_id'],
            ];
        }

        // License is valid: update cache timestamp and host seal
        self::writeCache([
            'is_locked'        => false,
            'lock_code'        => 'OK',
            'lock_reason'      => null,
            'last_verified_at' => $now,
            'machine_id'       => $status['machine_id'],
            'host_seal'        => $expectedSeal,
        ]);

        return [
            'valid'      => true,
            'code'       => 'OK',
            'machine_id' => $status['machine_id'],
        ];
    }

    /**
     * Saves an uploaded or provided license payload, purges cache, and verifies immediately.
     */
    public static function saveLicense(string $jsonContent): array
    {
        $decoded = json_decode($jsonContent, true);
        if (!is_array($decoded) || !isset($decoded['payload']) || !isset($decoded['signature'])) {
            return [
                'ok'    => false,
                'error' => 'Invalid license JSON format. Both payload and signature must be present.',
            ];
        }

        // 1. Cryptographically validate IN MEMORY before modifying any files on disk
        $status = self::verifyLicenseData($decoded);
        if (!$status['valid']) {
            return [
                'ok'         => false,
                'code'       => $status['code'],
                'error'      => $status['message'],
                'machine_id' => $status['machine_id'],
            ];
        }

        // 2. Only write to disk once proven authentic and valid for this machine
        $dir = dirname(self::LICENSE_PATH);
        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
        }
        $written = @file_put_contents(self::LICENSE_PATH, json_encode($decoded, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
        if ($written === false) {
            return [
                'ok'    => false,
                'error' => 'Failed to write license file. Check directory permissions for ' . $dir,
            ];
        }

        // Purge runtime lock cache
        self::purgeCache();

        // Update runtime cache with success
        self::writeCache([
            'is_locked'        => false,
            'lock_code'        => 'OK',
            'lock_reason'      => null,
            'last_verified_at' => time(),
            'machine_id'       => $status['machine_id'],
        ]);

        return [
            'ok'         => true,
            'message'    => 'License successfully installed and verified.',
            'payload'    => $status['payload'],
            'machine_id' => $status['machine_id'],
        ];
    }

    /**
     * Detects if system clock was rolled back.
     */
    public static function isClockTampered(): bool
    {
        try {
            if (!is_file(__DIR__ . '/../../config/database.php')) {
                return false;
            }
            require_once __DIR__ . '/../Database.php';
            $db = Database::getConnection();

            // Check latest log timestamp
            $stmt = $db->query("SELECT MAX(created_at) as latest FROM system_logs LIMIT 1");
            $row = $stmt->fetch();
            if (!empty($row['latest'])) {
                $latestLogTime = strtotime($row['latest']);
                // If current time is more than 10 minutes in the past of the latest recorded log, flag tampering
                if ($latestLogTime !== false && time() < ($latestLogTime - 600)) {
                    return true;
                }
            }
        } catch (\Throwable $e) {
            // DB unreachable or not yet configured
        }

        return false;
    }

    private static function readCache(): array
    {
        if (is_file(self::CACHE_PATH)) {
            $data = json_decode((string) file_get_contents(self::CACHE_PATH), true);
            if (is_array($data)) {
                return $data;
            }
        }
        return [];
    }

    private static function writeCache(array $data): void
    {
        if (!isset($data['host_seal'])) {
            $data['host_seal'] = MachineFingerprint::getHostSeal();
        }
        @file_put_contents(self::CACHE_PATH, json_encode($data, JSON_PRETTY_PRINT), LOCK_EX);
    }

    public static function purgeCache(): void
    {
        if (is_file(self::CACHE_PATH)) {
            @unlink(self::CACHE_PATH);
        }
    }

